CREATE TABLE usuarios (id BIGINT PRIMARY KEY AUTO_INCREMENT, nome VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, senha_hash VARCHAR(100) NOT NULL, ativo BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE recursos (id BIGINT PRIMARY KEY AUTO_INCREMENT, tipo VARCHAR(20) NOT NULL, codigo VARCHAR(80) NOT NULL UNIQUE, ativo BOOLEAN NOT NULL DEFAULT TRUE, restrito BOOLEAN NOT NULL DEFAULT FALSE, CHECK(tipo IN ('SALA','PROFESSOR','MATERIAL')), UNIQUE(id,tipo)) ENGINE=InnoDB;
CREATE TABLE salas (recurso_id BIGINT PRIMARY KEY, tipo VARCHAR(20) NOT NULL DEFAULT 'SALA', capacidade INT NOT NULL CHECK(capacidade>0), localizacao VARCHAR(200) NOT NULL, tipo_sala VARCHAR(80) NOT NULL, CHECK(tipo='SALA'), FOREIGN KEY(recurso_id,tipo) REFERENCES recursos(id,tipo)) ENGINE=InnoDB;
CREATE TABLE professores (recurso_id BIGINT PRIMARY KEY, tipo VARCHAR(20) NOT NULL DEFAULT 'PROFESSOR', nome VARCHAR(120) NOT NULL, CHECK(tipo='PROFESSOR'), FOREIGN KEY(recurso_id,tipo) REFERENCES recursos(id,tipo)) ENGINE=InnoDB;
CREATE TABLE professor_competencias (recurso_id BIGINT NOT NULL, competencia VARCHAR(120) NOT NULL, PRIMARY KEY(recurso_id,competencia), FOREIGN KEY(recurso_id) REFERENCES professores(recurso_id)) ENGINE=InnoDB;
CREATE TABLE materiais (recurso_id BIGINT PRIMARY KEY, tipo VARCHAR(20) NOT NULL DEFAULT 'MATERIAL', numero_patrimonio VARCHAR(80) NOT NULL UNIQUE, descricao VARCHAR(500) NOT NULL, condicao VARCHAR(120) NOT NULL, CHECK(tipo='MATERIAL'), FOREIGN KEY(recurso_id,tipo) REFERENCES recursos(id,tipo)) ENGINE=InnoDB;
CREATE TABLE configuracao_expediente (id INT PRIMARY KEY CHECK(id=1));
INSERT INTO configuracao_expediente VALUES(1);
CREATE TABLE horarios_funcionamento (id BIGINT PRIMARY KEY AUTO_INCREMENT, dia_semana INT NOT NULL CHECK(dia_semana BETWEEN 1 AND 7), hora_inicio TIME(6) NOT NULL, hora_fim TIME(6) NOT NULL, CHECK(hora_fim>hora_inicio)) ENGINE=InnoDB;
CREATE TABLE reservas (id BIGINT PRIMARY KEY AUTO_INCREMENT, solicitante_id BIGINT NOT NULL, inicio_utc DATETIME(6) NOT NULL, fim_utc DATETIME(6) NOT NULL, restrita BOOLEAN NOT NULL, status VARCHAR(24) NOT NULL, motivo_decisao VARCHAR(500), CHECK(fim_utc>inicio_utc), CHECK(status IN ('SOLICITADA','APROVADA','EM_USO','CONCLUIDA','REJEITADA','CANCELADA','NAO_COMPARECEU')), FOREIGN KEY(solicitante_id) REFERENCES usuarios(id), INDEX idx_periodo_status(inicio_utc,fim_utc,status)) ENGINE=InnoDB;
CREATE TABLE reserva_recursos (reserva_id BIGINT NOT NULL, recurso_id BIGINT NOT NULL, PRIMARY KEY(reserva_id,recurso_id), FOREIGN KEY(reserva_id) REFERENCES reservas(id), FOREIGN KEY(recurso_id) REFERENCES recursos(id), INDEX idx_rr_recurso(recurso_id,reserva_id)) ENGINE=InnoDB;
CREATE TABLE bloqueios_recursos (id BIGINT PRIMARY KEY AUTO_INCREMENT, recurso_id BIGINT NOT NULL, inicio_utc DATETIME(6) NOT NULL, fim_utc DATETIME(6) NOT NULL, motivo VARCHAR(500) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'ATIVO', autor_id BIGINT NOT NULL, cancelado_por BIGINT, cancelado_em DATETIME(6), CHECK(fim_utc>inicio_utc), CHECK(status IN ('ATIVO','CANCELADO')), FOREIGN KEY(recurso_id) REFERENCES recursos(id), FOREIGN KEY(autor_id) REFERENCES usuarios(id), FOREIGN KEY(cancelado_por) REFERENCES usuarios(id), INDEX idx_bloqueio(recurso_id,inicio_utc,fim_utc)) ENGINE=InnoDB;
CREATE TABLE movimentacoes (id BIGINT PRIMARY KEY AUTO_INCREMENT, recurso_id BIGINT NOT NULL, reserva_id BIGINT NOT NULL, responsavel_id BIGINT NOT NULL, retirado_em DATETIME(6) NOT NULL, devolvido_em DATETIME(6), devolvido_por BIGINT, fim_previsto DATETIME(6) NOT NULL, atraso_segundos BIGINT NOT NULL DEFAULT 0, recurso_aberto BIGINT GENERATED ALWAYS AS (CASE WHEN devolvido_em IS NULL THEN recurso_id ELSE NULL END) STORED, UNIQUE(recurso_aberto), FOREIGN KEY(recurso_id) REFERENCES materiais(recurso_id), FOREIGN KEY(reserva_id) REFERENCES reservas(id), FOREIGN KEY(responsavel_id) REFERENCES usuarios(id), FOREIGN KEY(devolvido_por) REFERENCES usuarios(id), CHECK(devolvido_em IS NULL OR devolvido_em>=retirado_em)) ENGINE=InnoDB;
CREATE TABLE conflitos_evitados (id BIGINT PRIMARY KEY AUTO_INCREMENT, solicitante_id BIGINT NOT NULL, recurso_id BIGINT NOT NULL, inicio_utc DATETIME(6) NOT NULL, fim_utc DATETIME(6) NOT NULL, origem VARCHAR(24) NOT NULL, momento DATETIME(6) NOT NULL, FOREIGN KEY(solicitante_id) REFERENCES usuarios(id), FOREIGN KEY(recurso_id) REFERENCES recursos(id)) ENGINE=InnoDB;
